import { COAT, coatFresnel, coatedPaperReflectance } from "./coat";
import { discProfile } from "./foilMaterial";
import { glslFloat as f } from "./glsl";
import { STILL_POSE } from "./lightMode";
// roomLight.json is generated by scripts/generateRoomLight.ts from roomGeometry.ts.
import roomLightMaps from "./roomLight.json";
import { ROOM, roomFrame, type RoomFrame } from "./sharedRoom";
import { VIEWING_CLASS } from "./viewing";

const roomLight = roomLightMaps[VIEWING_CLASS];

/**
 * The room's light falling on a sticker's paper, which shades its creases: the irradiance E(n) on a
 * surface facing n. The bounce surrounds the device, so it is projected once into spherical harmonics
 * in the room's axes (Ramamoorthi and Hanrahan). The direct part is the small ceiling light's power
 * times its incidence cosine; the crease shader accounts for its obstruction at raking light.
 */

type Vec3 = readonly [number, number, number];
const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: Vec3, b: Vec3): Vec3 => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];

/**
 * The room's bounce seen from the device, per unit of the ceiling light's radiance: an equirectangular
 * map in the room's axes (x the viewer's left, y toward the viewer, z up), column j from azimuth
 * 2πj/width, x toward y, and row i from polar angle πi/height, down from z. A texel's radiance is its
 * red byte over 255, times scale. The light itself is left out: roomShader draws it.
 */
export const ROOM_LIGHT = {
  width: roomLight.width,
  height: roomLight.height,
  scale: roomLight.scale,
  pixels: Uint8Array.from(atob(roomLight.pixels), (c) => c.charCodeAt(0)),
};

/** A direction in screen axes, as roomFrame gives them, in the room's axes. */
export function inRoomAxes(frame: RoomFrame, v: Vec3): Vec3 {
  // Screen axes are y down, so this cross product points to the viewer's left.
  const left = cross(frame.up, frame.toward);
  return [dot(v, left), dot(v, frame.toward), dot(v, frame.up)];
}

/**
 * The map summed over the sphere: each texel's radiance times its solid angle and `weight` at its
 * middle, a direction in the room's axes.
 */
export function overRoomLight(weight: (d: Vec3) => number) {
  const { width, height, scale, pixels } = ROOM_LIGHT;
  let sum = 0;
  for (let row = 0; row < height; row++) {
    const theta = (Math.PI * (row + 0.5)) / height;
    const solidAngle =
      ((2 * Math.PI) / width) *
      (Math.cos((Math.PI * row) / height) - Math.cos((Math.PI * (row + 1)) / height));
    for (let column = 0; column < width; column++) {
      const phi = (2 * Math.PI * (column + 0.5)) / width;
      const d: Vec3 = [
        Math.sin(theta) * Math.cos(phi),
        Math.sin(theta) * Math.sin(phi),
        Math.cos(theta),
      ];
      sum += ((weight(d) * pixels[(row * width + column) * 4]) / 255) * scale * solidAngle;
    }
  }
  return sum;
}

/**
 * The real spherical harmonics to band 2, each as its constant and its polynomial in a direction's
 * room axes, in TypeScript and GLSL.
 */
const HARMONICS = [
  { band: 0, constant: 0.282095, at: () => 1, glsl: "1." },
  { band: 1, constant: 0.488603, at: ([x]: Vec3) => x, glsl: "x" },
  { band: 1, constant: 0.488603, at: ([, y]: Vec3) => y, glsl: "y" },
  { band: 1, constant: 0.488603, at: ([, , z]: Vec3) => z, glsl: "z" },
  { band: 2, constant: 1.092548, at: ([x, y]: Vec3) => x * y, glsl: "x*y" },
  { band: 2, constant: 1.092548, at: ([, y, z]: Vec3) => y * z, glsl: "y*z" },
  { band: 2, constant: 1.092548, at: ([x, , z]: Vec3) => x * z, glsl: "x*z" },
  { band: 2, constant: 0.315392, at: ([, , z]: Vec3) => 3 * z * z - 1, glsl: "(3.*z*z-1.)" },
  { band: 2, constant: 0.546274, at: ([x, y]: Vec3) => x * x - y * y, glsl: "(x*x-y*y)" },
] as const;
/** Each band's cosine convolution. */
const CONVOLUTION = [Math.PI, (2 * Math.PI) / 3, Math.PI / 4];

/**
 * The bounce's irradiance per unit of the light's radiance, as each harmonic's factor on its
 * polynomial: the light's azimuth breaks left for right, so every term stays.
 */
const BOUNCE = HARMONICS.map(
  ({ band, constant, at }) => CONVOLUTION[band] * constant * constant * overRoomLight(at),
);

/** The bounce's irradiance per unit of the light's radiance on a surface facing n, in the room's axes. */
export function bounceIrradiance(n: Vec3) {
  return HARMONICS.reduce((sum, { at }, i) => sum + BOUNCE[i] * at(n), 0);
}

/**
 * The ceiling light's body, edge blur included, summed over its ellipse on its plane one unit along
 * it: each patch weighted by `weight` at its place, x across and y down, and by the solid angle it
 * covers.
 */
export function overLightBody(weight: (x: number, y: number) => number) {
  const { light } = ROOM;
  const rings = 512;
  const spokes = 32;
  const reach = light.radius + 12 * light.feather;
  let sum = 0;
  for (let i = 0; i < rings; i++) {
    // q is the distance from the middle with down stretched by the aspect, as roomShader's roomDisc takes it.
    const q = ((i + 0.5) / rings) * reach;
    const ring =
      discProfile(q, light) * light.aspect * q * (reach / rings) * ((2 * Math.PI) / spokes);
    for (let k = 0; k < spokes; k++) {
      const angle = (2 * Math.PI * (k + 0.5)) / spokes;
      const x = q * Math.cos(angle);
      const y = light.aspect * q * Math.sin(angle);
      // A patch seen from one unit before the plane: dω = dA / (1 + x² + y²)^(3/2).
      sum += (weight(x, y) * ring) / (1 + x * x + y * y) ** 1.5;
    }
  }
  return sum;
}

/** The solid angle the light's body covers, edge blur included, as gloss mirrors it. */
const LIGHT_SOLID_ANGLE = overLightBody(() => 1);

/**
 * The ceiling light's radiance, set by the exposure: white paper at the still pose, seen square-on,
 * shows paper white W, so W = L·[R(disc)·E_disc + ∫R(cos θ)·bounce·cos θ dω]/π, where R is white
 * paper's reflectance under the coat for light arriving at that cosine. Lumens and lux cancel: the
 * room's bounce is per unit of the light's radiance, so only W and the room's geometry set it.
 */
export const LIGHT_RADIANCE = (() => {
  const still = roomFrame(STILL_POSE);
  const normal = inRoomAxes(still, [0, 0, 1]);
  const toLight = still.light[2];
  const bounce = overRoomLight((d) => {
    const cosine = dot(normal, d);
    return cosine > 0 ? coatedPaperReflectance(cosine) * cosine : 0;
  });
  const reflected = coatedPaperReflectance(toLight) * LIGHT_SOLID_ANGLE * toLight + bounce;
  return (Math.PI * COAT.paperWhite) / reflected;
})();

/** Design decision: preserve highlight headroom without changing the light falling on the print. */
export const LIGHT_REFLECTION_RADIANCE = Math.min(
  LIGHT_RADIANCE,
  (0.5 * COAT.paperWhite) / coatFresnel(1),
);

/**
 * The ceiling light's power: its radiance times the solid angle its body covers. Its veil scatters in
 * the eye, so no paper receives it.
 */
const LIGHT_POWER = LIGHT_RADIANCE * LIGHT_SOLID_ANGLE;

/** The shader's roomIrradiance on paper facing n, in screen axes: the ceiling light's part and the whole. */
export function paperIrradiance(frame: RoomFrame, n: Vec3 = [0, 0, 1]) {
  const bounce = LIGHT_RADIANCE * bounceIrradiance(inRoomAxes(frame, n));
  const light = LIGHT_POWER * Math.max(dot(n, frame.light), 0);
  return { light, total: bounce + light };
}

/**
 * roomIrradiance(n): the irradiance on paper facing n, in screen axes; roomLightIrradiance(n), the
 * ceiling light's part, which a shadow takes away. Needs roomFragment first.
 */
export const roomIrradianceFragment = `
float roomLightIrradiance(vec3 n){
 return ${f(LIGHT_POWER)}*max(dot(n,roomLight),0.);
}
float roomIrradiance(vec3 n){
 vec3 left=cross(roomUp,roomToward);
 float x=dot(n,left),y=dot(n,roomToward),z=dot(n,roomUp);
 return ${HARMONICS.map(({ glsl }, i) => `${f(LIGHT_RADIANCE * BOUNCE[i])}*${glsl}`).join("+")}
  +roomLightIrradiance(n);
}
`;
